  "revision": {
    "quickRevision": [
      "Improvement in food resources aims at higher and better-quality production with sustainable management.",
      "Crop variety improvement targets yield, quality, resistance and adaptability.",
      "Plants need macronutrients and micronutrients.",
      "Manure adds organic matter; fertilisers supply concentrated nutrients.",
      "Irrigation supplies water at suitable times.",
      "Mixed cropping, intercropping and crop rotation are distinct strategies.",
      "Crop protection includes weeds, pests, pathogens and storage losses.",
      "Animal husbandry includes breeding, feeding, housing and disease control.",
      "Fisheries include capture and culture; aquaculture is managed farming of aquatic organisms.",
      "Apiculture is scientific bee-keeping."
    ],
    "importantQuestions": [
      "Explain crop variety improvement goals.",
      "Differentiate manure and fertiliser.",
      "Compare mixed cropping, intercropping and crop rotation.",
      "Explain integrated crop protection.",
      "Describe cattle and poultry management.",
      "Explain composite fish culture.",
      "Explain the importance of bee-keeping."
    ]
  },
  "glossary": [
    {
      "front": "Need for Improvement in Food Resources",
      "back": "Improvement in food resources aims to increase food quantity and quality while using land, water and other resources efficiently."
    },
    {
      "front": "Crop Variety Improvement",
      "back": "Crop variety improvement develops or selects varieties with desirable traits such as high yield, quality and resistance to stresses."
    },
    {
      "front": "Crop Production Management",
      "back": "Crop production management includes nutrient management, irrigation, cropping patterns and other practices used to obtain good crop yield."
    },
    {
      "front": "Nutrients: Macronutrients and Micronutrients",
      "back": "Plants require macronutrients in relatively large amounts and micronutrients in much smaller amounts for healthy growth."
    },
    {
      "front": "Manure",
      "back": "Manure is decomposed plant and animal waste that adds organic matter and nutrients to soil."
    },
    {
      "front": "Fertilisers",
      "back": "Fertilisers are concentrated nutrient materials supplied to crops to provide specific mineral nutrients."
    },
    {
      "front": "Irrigation",
      "back": "Irrigation is the artificial supply of water to crops at suitable intervals."
    },
    {
      "front": "Cropping Patterns",
      "back": "Cropping patterns are planned arrangements of crops, including mixed cropping, intercropping and crop rotation."
    },
    {
      "front": "Crop Protection Management",
      "back": "Crop protection management prevents or reduces losses caused by weeds, pests, diseases and poor storage conditions."
    },
    {
      "front": "Animal Husbandry",
      "back": "Animal husbandry is the scientific management of domesticated animals for useful products."
    },
    {
      "front": "Cattle Farming",
      "back": "Cattle farming involves suitable breeds, feeding, shelter, breeding and disease control for cattle reared for milk or draught work."
    },
    {
      "front": "Poultry Farming",
      "back": "Poultry farming is the scientific rearing of birds such as chickens for eggs and meat."
    },
    {
      "front": "Fish Production",
      "back": "Fish production is obtaining fish through capture fisheries or controlled culture systems."
    },
    {
      "front": "Bee-keeping",
      "back": "Bee-keeping is the scientific management of honeybee colonies for honey, beeswax and pollination benefits."
    },
    {
      "front": "Fisheries and Aquaculture",
      "back": "Fisheries involve harvesting aquatic organisms, while aquaculture involves their controlled breeding and rearing."
    },
    {
      "front": "Sustainable Food Production",
      "back": "Sustainable food production meets present food needs while conserving soil, water, biodiversity and future productivity."
    }
  ],
